// @vitest-environment jsdom
// The booking editor (decisions/0080 spec section 5) driven like a user would: plain-word
// fields in, the right base lines out to the (mocked) Server Action. The tax lines themselves
// are generated by the use case with the same `expandTaxLines`; the live preview shows them.
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { act, cleanup, fireEvent, render, screen, within } from "@testing-library/react";
import { NextIntlClientProvider } from "next-intl";

import de from "@/i18n/messages/de.json";

const createMock = vi.fn();
const updateMock = vi.fn();
const bookMock = vi.fn();
const learnMock = vi.fn();
vi.mock("../actions", () => ({
  createJournalEntryAction: (input: unknown) => createMock(input),
  updateJournalEntryAction: (input: unknown) => updateMock(input),
  bookJournalEntryAction: (input: unknown) => bookMock(input),
  learnLedgerRuleFromEntryAction: (input: unknown) => learnMock(input),
  deleteJournalEntryAction: vi.fn(),
  dismissProposalAction: vi.fn(),
  restoreProposalAction: vi.fn(),
  unbookJournalEntryAction: vi.fn(),
}));

const pushMock = vi.fn();
const refreshMock = vi.fn();
vi.mock("next/navigation", () => ({ useRouter: () => ({ push: pushMock, refresh: refreshMock }) }));

import { expandTaxLines } from "../core/tax-codes";
import type { LedgerAccountView } from "../core/types";
import { EntryEditor, type EditorEntry } from "../ui/entry-editor";

function account(number: string, name: string, kind: LedgerAccountView["kind"], group: LedgerAccountView["group"], extra: Partial<LedgerAccountView> = {}): LedgerAccountView {
  return {
    id: `acc-${number}`,
    number,
    name,
    kind,
    group,
    openItems: false,
    ownerType: null,
    ownerBankAccountId: null,
    ownerContactId: null,
    ownerPlatform: null,
    ownerPersonName: null,
    description: null,
    archived: false,
    ...extra,
  };
}

const ACCOUNTS: LedgerAccountView[] = [
  account("1800", "Finom Main", "asset", "bank", { ownerType: "bank_account", ownerBankAccountId: "bank-1" }),
  account("1461", "Verrechnung Meta", "asset", "open_items", { openItems: true, ownerType: "contact", ownerContactId: "contact-meta" }),
  account("3300", "Verbindlichkeiten aus Lieferungen und Leistungen", "liability", "open_items", { openItems: true }),
  account("1200", "Forderungen aus Lieferungen und Leistungen", "asset", "open_items", { openItems: true }),
  account("1406", "Abziehbare Vorsteuer 19 %", "asset", "taxes"),
  account("1407", "Abziehbare Vorsteuer § 13b UStG 19 %", "asset", "taxes"),
  account("3837", "Umsatzsteuer nach § 13b UStG 19 %", "liability", "taxes"),
  account("6810", "Internetkosten", "expense", "costs"),
  account("6600", "Werbekosten", "expense", "costs"),
  account("6825", "Rechts- und Beratungskosten", "expense", "costs"),
  account("6855", "Nebenkosten des Geldverkehrs", "expense", "costs"),
];

const NEW_ENTRY: EditorEntry = {
  id: null,
  status: null,
  dismissed: false,
  origin: "manual",
  revision: 0,
  bookingDate: "2026-09-03",
  documentDate: null,
  serviceDate: null,
  text: "",
  documentId: null,
  transactionId: null,
  correctionOfEntryId: null,
  filingId: null,
  lines: [],
};

function renderEditor(props: Partial<React.ComponentProps<typeof EntryEditor>> = {}) {
  return render(
    <NextIntlClientProvider locale="de" messages={{ Ledger: de.Ledger }} timeZone="Europe/Berlin">
      <EntryEditor entry={NEW_ENTRY} seed="entry" accounts={ACCOUNTS} sourceDocument={null} sourceTransaction={null} canManage lockedBy={null} ruleSubject={null} {...props} />
    </NextIntlClientProvider>,
  );
}

function pickAccount(combobox: HTMLElement, number: string) {
  fireEvent.focus(combobox);
  fireEvent.change(combobox, { target: { value: number } });
  fireEvent.keyDown(combobox, { key: "Enter" });
}

function type(label: string | RegExp, value: string) {
  fireEvent.change(screen.getByLabelText(label), { target: { value } });
}

const bookButton = () => screen.getByRole("button", { name: "Buchen" }) as HTMLButtonElement;

beforeEach(() => {
  createMock.mockResolvedValue({ status: "success", data: { entryId: "11111111-1111-4111-8111-111111111111" } });
  updateMock.mockResolvedValue({ status: "success", data: { entryId: "e", revision: 3 } });
  bookMock.mockResolvedValue({ status: "success", data: undefined });
  learnMock.mockResolvedValue({ status: "success", data: {} });
});

afterEach(() => {
  cleanup();
  vi.clearAllMocks();
});

describe("EntryEditor, simple modes", () => {
  it("books IONOS 1,50 with 19 % Vorsteuer paid by bank", async () => {
    renderEditor();
    pickAccount(screen.getByRole("combobox", { name: "Wofür?" }), "6810");
    type("Betrag", "1,50");
    type("Steuer", "vst19");
    type("Bezahlt über", "1800");
    type("Buchungstext", "IONOS Rechnung 2026-0612");

    // The live preview, generated tax line included.
    const preview = screen.getByRole("table", { name: "So wird gebucht" });
    expect(within(preview).getByText("Abziehbare Vorsteuer 19 %")).toBeTruthy();
    expect(within(preview).getByText("0,24 €")).toBeTruthy();
    expect(within(preview).getByText("Ausgeglichen")).toBeTruthy();
    expect(screen.getByText(/Rechnung eines deutschen Anbieters mit 19 %/)).toBeTruthy();

    await act(async () => {
      fireEvent.click(bookButton());
    });
    expect(createMock).toHaveBeenCalledTimes(1);
    const { entry, book } = createMock.mock.calls[0]![0] as { entry: { lines: unknown[]; text: string; bookingDate: string }; book: boolean };
    expect(book).toBe(true);
    expect(entry.text).toBe("IONOS Rechnung 2026-0612");
    expect(entry.lines).toEqual([
      expect.objectContaining({ accountNumber: "6810", amountCents: 150, taxCode: "vst19", amountMode: "gross" }),
      expect.objectContaining({ accountNumber: "1800", amountCents: -150, taxCode: null }),
    ]);
    expect(expandTaxLines(entry.lines as never).map((line) => [line.accountNumber, line.amountCents])).toEqual([
      ["6810", 126],
      ["1406", 24],
      ["1800", -150],
    ]);
    expect(pushMock).toHaveBeenCalledWith("/dashboard/buchhaltung/buchung/11111111-1111-4111-8111-111111111111");
  });

  it("books a Meta invoice under reverse charge against the Meta clearing account", async () => {
    renderEditor();
    pickAccount(screen.getByRole("combobox", { name: "Wofür?" }), "6600");
    type("Betrag", "13,00");
    type("Steuer", "rc13b");
    type("Bezahlt über", "1461");
    type("Buchungstext", "Meta FBADS-1188");
    const preview = screen.getByRole("table", { name: "So wird gebucht" });
    expect(within(preview).getByText("Abziehbare Vorsteuer § 13b UStG 19 %")).toBeTruthy();
    expect(within(preview).getByText("Umsatzsteuer nach § 13b UStG 19 %")).toBeTruthy();
    expect(within(preview).getAllByText("2,47 €")).toHaveLength(2);

    await act(async () => {
      fireEvent.click(bookButton());
    });
    const { entry } = createMock.mock.calls[0]![0] as { entry: { lines: unknown[] } };
    expect(entry.lines).toEqual([
      expect.objectContaining({ accountNumber: "6600", amountCents: 1300, taxCode: "rc13b" }),
      expect.objectContaining({ accountNumber: "1461", amountCents: -1300 }),
    ]);
  });

  it("splits the court letter into 300 and 5 and books only when nothing is left to distribute", async () => {
    renderEditor();
    fireEvent.click(screen.getByRole("tab", { name: "Aufteilen" }));
    type("Gesamtbetrag", "305,00");
    pickAccount(screen.getByRole("combobox", { name: "Konto der Position 1" }), "6825");
    type("Betrag der Position 1", "300,00");
    type("Steuer der Position 1", "not_taxable");
    pickAccount(screen.getByRole("combobox", { name: "Konto der Position 2" }), "6855");
    type("Betrag der Position 2", "4,00");
    type("Steuer der Position 2", "not_taxable");
    type("Buchungstext", "Amtsgericht Bonn, Gerichtskosten und Mahngebühr");
    expect(screen.getByText("Noch zu verteilen: 1,00 €")).toBeTruthy();
    expect(bookButton().disabled).toBe(true);

    type("Betrag der Position 2", "5,00");
    expect(screen.getByText("Noch zu verteilen: 0,00 €")).toBeTruthy();
    expect(bookButton().disabled).toBe(false);
    await act(async () => {
      fireEvent.click(bookButton());
    });
    const { entry } = createMock.mock.calls[0]![0] as { entry: { lines: unknown[] } };
    expect(entry.lines).toEqual([
      expect.objectContaining({ accountNumber: "6825", amountCents: 30000, taxCode: "not_taxable" }),
      expect.objectContaining({ accountNumber: "6855", amountCents: 500, taxCode: "not_taxable" }),
      expect.objectContaining({ accountNumber: "3300", amountCents: -30500 }),
    ]);
  });
});

describe("EntryEditor, expert mode", () => {
  it("blocks booking while Soll and Haben differ", () => {
    renderEditor({ entry: { ...NEW_ENTRY, text: "Gerichtskosten" } });
    fireEvent.click(screen.getByRole("tab", { name: "Experte" }));
    pickAccount(screen.getByRole("combobox", { name: "Konto der Zeile 1" }), "6825");
    type("Soll der Zeile 1", "300,00");
    pickAccount(screen.getByRole("combobox", { name: "Konto der Zeile 2" }), "1800");
    type("Haben der Zeile 2", "305,00");
    expect(bookButton().disabled).toBe(true);
    expect(screen.getByText("Soll und Haben sind nicht gleich.")).toBeTruthy();
    expect(within(screen.getByRole("table", { name: "So wird gebucht" })).getByText("Differenz 5,00 €")).toBeTruthy();
    // A proposal may stay unbalanced while it is being worked on.
    expect((screen.getByRole("button", { name: "Als Vorschlag speichern" }) as HTMLButtonElement).disabled).toBe(false);

    type("Haben der Zeile 2", "300,00");
    expect(bookButton().disabled).toBe(false);
  });

  it("does not squeeze a multi-line expert entry back into Ausgabe", () => {
    renderEditor();
    fireEvent.click(screen.getByRole("tab", { name: "Experte" }));
    pickAccount(screen.getByRole("combobox", { name: "Konto der Zeile 1" }), "6825");
    type("Soll der Zeile 1", "300");
    pickAccount(screen.getByRole("combobox", { name: "Konto der Zeile 2" }), "6855");
    type("Soll der Zeile 2", "5");
    fireEvent.click(screen.getByRole("button", { name: "Zeile hinzufügen" }));
    pickAccount(screen.getByRole("combobox", { name: "Konto der Zeile 3" }), "1800");
    type("Haben der Zeile 3", "200");
    fireEvent.click(screen.getByRole("tab", { name: "Ausgabe" }));
    expect(screen.getByRole("alert").textContent).toContain("passt in keine Vorlage");
    expect(screen.getByRole("tab", { name: "Experte" }).getAttribute("aria-selected")).toBe("true");
  });
});

describe("EntryEditor, existing entries", () => {
  const ionosLines = expandTaxLines([
    { accountNumber: "6810", amountCents: 150, taxCode: "vst19" },
    { accountNumber: "1800", amountCents: -150 },
  ]);
  const booked: EditorEntry = { ...NEW_ENTRY, id: "22222222-2222-4222-8222-222222222222", status: "booked", origin: "rule", revision: 2, text: "IONOS", lines: ionosLines };

  it("opens a booked entry in Ausgabe with its gross amount", () => {
    renderEditor({ entry: booked });
    expect(screen.getByRole("tab", { name: "Ausgabe" }).getAttribute("aria-selected")).toBe("true");
    expect((screen.getByLabelText("Betrag") as HTMLInputElement).value).toBe("1,50");
  });

  it("requires a reason before saving a change to a booked entry", async () => {
    renderEditor({ entry: booked });
    type("Betrag", "1,60");
    await act(async () => {
      fireEvent.click(screen.getByRole("button", { name: "Änderungen speichern" }));
    });
    expect(updateMock).not.toHaveBeenCalled();
    expect(screen.getByRole("alert").textContent).toBe("Bitte geben Sie einen Grund an.");

    type("Grund der Änderung", "Rechnung korrigiert");
    await act(async () => {
      fireEvent.click(screen.getByRole("button", { name: "Änderungen speichern" }));
    });
    expect(updateMock).toHaveBeenCalledWith(expect.objectContaining({ entryId: booked.id, reason: "Rechnung korrigiert", expectedRevision: 2 }));
    expect(refreshMock).toHaveBeenCalled();
  });

  it("shows a stale revision with a reload button", async () => {
    updateMock.mockResolvedValue({ status: "error", errorCode: "stale_revision" });
    renderEditor({ entry: booked });
    type("Betrag", "1,60");
    type("Grund der Änderung", "Korrektur");
    await act(async () => {
      fireEvent.click(screen.getByRole("button", { name: "Änderungen speichern" }));
    });
    expect(screen.getByRole("alert").textContent).toContain("Wurde inzwischen geändert.");
    fireEvent.click(screen.getByRole("button", { name: "Neu laden" }));
    expect(refreshMock).toHaveBeenCalled();
  });

  it("books an edited proposal after saving it, learns the rule, and returns to the queue", async () => {
    const proposal: EditorEntry = { ...booked, status: "proposed", origin: "ai" };
    renderEditor({ entry: proposal, ruleSubject: "IONOS SE" });
    const learn = screen.getByRole("checkbox", { name: /Für IONOS SE künftig so vorschlagen/ }) as HTMLInputElement;
    expect(learn.checked).toBe(true);
    pickAccount(screen.getByRole("combobox", { name: "Wofür?" }), "6600");
    await act(async () => {
      fireEvent.click(bookButton());
    });
    expect(updateMock).toHaveBeenCalledWith(expect.objectContaining({ entryId: proposal.id, reason: null }));
    expect(bookMock).toHaveBeenCalledWith({ entryId: proposal.id });
    expect(learnMock).toHaveBeenCalledWith({ entryId: proposal.id });
    expect(pushMock).toHaveBeenCalledWith("/dashboard/buchhaltung/zu-pruefen");
  });

  it("makes a locked entry read-only and offers the correction", () => {
    renderEditor({ entry: booked, lockedBy: { id: "f", kind: "vat_return", periodFrom: "2026-07-01", periodTo: "2026-09-30" } });
    expect(screen.getByText("Gesperrt durch USt-VA 3. Quartal 2026")).toBeTruthy();
    expect((screen.getByLabelText("Betrag") as HTMLInputElement).disabled).toBe(true);
    expect(screen.queryByRole("button", { name: "Änderungen speichern" })).toBeNull();
    expect(screen.getByRole("link", { name: "Korrektur buchen" }).getAttribute("href")).toBe(`/dashboard/buchhaltung/buchung/neu?korrektur=${booked.id}`);
  });
});
